before(() => { Object.assign(process.env, environment); });
after(() => { for (const [name, value] of Object.entries(previous)) { if (value === undefined) delete process.env[name]; else process.env[name] = value; } });

test('a valid Draft v2 parses to itself, and a draftless default is empty, unknown and public', () => {
    assert.deepEqual(parseDraftV2(draft(), manifest), draft());
    const empty = defaultDraftV2(manifest);
    assert.deepEqual(empty, { album: { title: '', artists: [], label: null, releaseDate: null, visibility: 'public' }, tracks: manifest.files.map(file => ({ slotId: file.slotId, title: '', discNumber: null, trackNumber: null })) });
    assert.deepEqual(parseDraftV2(empty, manifest), empty); assert.equal(isDraftV2(empty), true);
    assert.equal(isDraftV2({ album: { artistName: 'x', artists: [] }, tracks: [] }), false); assert.equal(isDraftV2({ album: { title: '' }, tracks: [] }), false);
});

test('Artist entries keep every primary before every featured entry and unique case-insensitive NFC names', () => {
    assert.deepEqual(parseArtistEntries([entry(1, 'A'), entry(2, 'B', 'featured')], []).map(value => value.role), ['primary', 'featured']);
    assert.deepEqual(parseArtistEntries([entry(1, 'Only guest', 'featured')], []).map(value => value.role), ['featured']);
    invalid(() => parseArtistEntries([entry(1, 'A', 'featured'), entry(2, 'B')], []), 'featured before primary');
    invalid(() => parseArtistEntries([entry(1, 'A'), entry(2, 'B', 'featured'), entry(3, 'C')], []), 'primary after featured');
    invalid(() => parseArtistEntries([entry(1, 'A', 'performer' as 'primary')], []), 'unknown role');
    invalid(() => parseArtistEntries([entry(1, 'Lorem'), entry(2, 'LOREM')], []), 'case-insensitive duplicate');
    invalid(() => parseArtistEntries([entry(1, 'Caf\u00E9'), entry(2, 'CAFE\u0301')], []), 'NFC duplicate');
    assert.equal(foldImportName('CAFE\u0301'), foldImportName('caf\u00E9'));
    // NFC and trimming apply before storage.
    assert.equal(parseArtistEntries([entry(1, '  Cafe\u0301  ')], [])[0].name, 'Caf\u00E9');
});

test('Artist names reject controls, invisible formatting characters, lone surrogates and length or emptiness violations', () => {
    for (const name of ['A\u0007B', 'A\u0085B', 'A\u200BB', 'A\u200EB', 'A\u2060B', 'A\uFEFFB', 'A\u200DB', 'A\u00ADB', 'A\uD800', '\uDC00A', '', '   ', 'x'.repeat(201), 42, null]) {
        invalid(() => parseImportName(name), JSON.stringify(name)); invalid(() => parseArtistEntries([entry(1, name as string)], []), JSON.stringify(name));
    }
    assert.equal(parseImportName('x'.repeat(200)).length, 200);
    invalid(() => parseImportName(` ${'y'.repeat(200)} `), 'the bound applies before trimming');
    invalid(() => parseLabelEntry({ name: 'Label\u200B', musicBrainzId: null }, null));
});

test('Artist entry lists are bounded, need unique UUID keys and exact keys, and lowercase their keys', () => {
    const twenty = Array.from({ length: 20 }, (_, index) => entry(index + 1, `Name ${index}`));
    assert.equal(parseArtistEntries(twenty, []).length, 20);
    invalid(() => parseArtistEntries([...twenty, entry(21, 'Name 20')], []), '21 entries');
    invalid(() => parseArtistEntries([entry(1, 'A'), entry(1, 'B')], []), 'duplicate key');
    invalid(() => parseArtistEntries([entry(1, 'A'), { ...entry(2, 'B'), key: key(1).toUpperCase() }], []), 'duplicate key differing in case');
    invalid(() => parseArtistEntries([{ ...entry(1, 'A'), key: 'not-a-uuid' }], []), 'invalid key');
    assert.equal(parseArtistEntries([{ ...entry(1, 'A'), key: key(1).toUpperCase() }], [])[0].key, key(1));
    invalid(() => parseArtistEntries({ 0: entry(1, 'A') }, []), 'not an array');
    invalid(() => parseArtistEntries([{ ...entry(1, 'A'), extra: true }], []), 'extra entry key');
    const { musicBrainzId: _id, ...missing } = entry(1, 'A'); invalid(() => parseArtistEntries([missing], []), 'missing entry key');
    // Canonical key order, so stored values compare equal to client bases.
    assert.deepEqual(Object.keys(parseArtistEntries([{ musicBrainzId: null, joinPhrase: null, role: 'primary', name: 'A', key: key(1) }], [])[0]), ['key', 'name', 'role', 'joinPhrase', 'musicBrainzId']);
});

test('join phrases use the Credit phrase rules, and editing one never changes a role', () => {
    for (const phrase of ['\u3001', ' & ', ' feat. ']) assert.equal(parseArtistEntries([entry(1, 'A', 'primary', { joinPhrase: phrase })], [])[0].joinPhrase, phrase);
    for (const phrase of ['', ' ', '\u200B', 'x'.repeat(17), 7]) invalid(() => parseArtistEntries([entry(1, 'A', 'primary', { joinPhrase: phrase as string })], []), JSON.stringify(phrase));
    const target = { draft: withAlbum({ artists: [entry(1, 'A', 'primary', { joinPhrase: ' & ' }), entry(2, 'B', 'featured')] }), draftOrigins: {} as ImportDraftOrigins };
    const value = target.draft.album.artists.map(item => item.key === key(1) ? { ...item, joinPhrase: ' with ' } : item);
    applyAdministratorChanges(target, parseDraftChanges([{ path: 'album.artists', base: target.draft.album.artists, value }], manifest, target.draft));
    assert.deepEqual(target.draft.album.artists.map(item => [item.role, item.joinPhrase]), [['primary', ' with '], ['featured', null]]);
});

test('Disc Numbers, Track Numbers and titles are bounded', () => {
    const track = (change: object) => { const value = draft(); Object.assign(value.tracks[0], change); return value; };
    for (const discNumber of [1, 999, null]) assert.equal(parseDraftV2(track({ discNumber }), manifest).tracks[0].discNumber, discNumber);
    for (const discNumber of [0, 1000, 1.5, -1, '1']) invalid(() => parseDraftV2(track({ discNumber }), manifest), `disc ${discNumber}`);
    for (const trackNumber of [1, 9999]) assert.equal(parseDraftV2(track({ trackNumber }), manifest).tracks[0].trackNumber, trackNumber);
    for (const trackNumber of [0, 10000, 2.5]) invalid(() => parseDraftV2(track({ trackNumber }), manifest), `track ${trackNumber}`);
    assert.equal(parseDraftV2(withAlbum({ title: 't'.repeat(300) }), manifest).album.title.length, 300);
    invalid(() => parseDraftV2(withAlbum({ title: 't'.repeat(301) }), manifest)); invalid(() => parseDraftV2(track({ title: 't'.repeat(301) }), manifest));
    invalid(() => parseDraftV2(withAlbum({ visibility: 'unlisted' as 'public' }), manifest));
});

test('Draft v2 keys are exact at every level, with one track per manifest slot', () => {
    const value = draft();
    for (const changed of [{ ...value, extra: 1 }, { ...value, album: { ...value.album, artistName: 'Lorem' } }, { ...value, tracks: [{ ...value.tracks[0], extra: 1 }, value.tracks[1]] },
        { ...value, album: { ...value.album, label: { name: 'Label', musicBrainzId: null, extra: 1 } } }, { ...value, album: { ...value.album, label: { name: 'Label' } } },
        { album: value.album }, { ...value, tracks: [value.tracks[0]] }, { ...value, tracks: [value.tracks[0], value.tracks[0]] },
        { ...value, tracks: [value.tracks[0], { ...value.tracks[1], slotId: '00000009-0000-4000-a000-0000000000ff' }] }, { ...value, tracks: [{ slotId: slotA, title: 'One', trackNumber: 1 }, value.tracks[1]] }]) invalid(() => parseDraftV2(changed, manifest), JSON.stringify(changed).slice(0, 80));
    assert.deepEqual(parseDraftV2(withAlbum({ label: { name: ' Synthetic Label ', musicBrainzId: null } }), manifest).album.label, { name: 'Synthetic Label', musicBrainzId: null });
});

test('a client MusicBrainz ID is kept only when it equals the one stored for the same, unrenamed entry or label', () => {
    const stored = [entry(1, 'Lorem Ensemble', 'primary', { musicBrainzId: mbid(1) })];
    invalid(() => parseArtistEntries([entry(1, 'Lorem Ensemble', 'primary', { musicBrainzId: mbid(1) })], []), 'no stored ID');
    assert.equal(parseArtistEntries([entry(1, 'Lorem Ensemble', 'primary', { musicBrainzId: mbid(1).toUpperCase() })], stored)[0].musicBrainzId, mbid(1));
    assert.equal(parseArtistEntries([entry(1, 'LOREM ensemble', 'primary', { musicBrainzId: mbid(1) })], stored)[0].musicBrainzId, mbid(1), 'a case-only rename keeps it');
    invalid(() => parseArtistEntries([entry(1, 'Renamed', 'primary', { musicBrainzId: mbid(1) })], stored), 'renamed');
    invalid(() => parseArtistEntries([entry(1, 'Lorem Ensemble', 'primary', { musicBrainzId: mbid(2) })], stored), 'different ID');
    invalid(() => parseArtistEntries([entry(2, 'Lorem Ensemble', 'primary', { musicBrainzId: mbid(1) })], stored), 'another entry key');
    invalid(() => parseArtistEntries([entry(1, 'Lorem Ensemble', 'primary', { musicBrainzId: 'not-an-id' })], stored), 'malformed');
    assert.equal(parseArtistEntries([entry(1, 'Renamed')], stored)[0].musicBrainzId, null, 'renaming may always drop the ID');
    const label = { name: 'Synthetic Label', musicBrainzId: mbid(3) };
    assert.deepEqual(parseLabelEntry(label, label), label); invalid(() => parseLabelEntry(label, null)); invalid(() => parseLabelEntry({ ...label, name: 'Other' }, label));
});

test('the 48 KB cap refuses a growing draft but keeps a converted draft near the cap editable', () => {
    const files = Array.from({ length: 100 }, (_, index) => ({ slotId: `00000009-0000-4000-a000-${String(index).padStart(12, '0')}`, filename: `${index}.mp3`, relativePath: `${index}.mp3`, byteLength: null }));
    const large: ImportManifest = { rootLabel: '', files };
    const big = { ...defaultDraftV2(large), tracks: files.map(file => ({ slotId: file.slotId, title: '\u6F22'.repeat(300), discNumber: null, trackNumber: null })) };
    invalid(() => parseDraftV2(big, large), 'over the cap');
    const smaller = structuredClone(big); smaller.tracks[0].title = 'short';
    const larger = structuredClone(big); larger.album.title = 'longer title';
    assert.equal(draftWithinSizeLimit(big, smaller), true); assert.equal(draftWithinSizeLimit(big, larger), false); assert.equal(draftWithinSizeLimit(big, big), true);
    assert.equal(draftWithinSizeLimit(draft(), withAlbum({ title: 'A slightly longer title' })), true);
});

