test('a stored value the editor view cannot show is replaced by a save from the shown value, while any other base stays stale', () => {
    // A v1 value accepted before NFC: 150 U+0958 store 300 code units, over the 200-unit name bound, so the view shows no entry.
    const nukta = String.fromCodePoint(0x958), long = nukta.repeat(150).normalize('NFC'), title = nukta.repeat(200).normalize('NFC');
    const stored = withAlbum({ artists: [entry(1, long)] }); stored.tracks[0].title = title;
    const shown = importDraftV2View(stored, manifest, 'a'.repeat(24));
    assert.deepEqual([long.length, shown.album.artists, shown.tracks[0].title], [300, [], '']);
    const target = { draft: structuredClone(stored), draftOrigins: {} as ImportDraftOrigins };
    assert.throws(() => applyAdministratorChanges(target, parseDraftChanges([{ path: `tracks.${slotA}.title`, base: 'Something else', value: 'Short' }], manifest, target.draft), shown), refused('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.throws(() => applyAdministratorChanges(target, parseDraftChanges([{ path: `tracks.${slotA}.title`, base: '', value: 'Short' }], manifest, target.draft)), refused('ADMIN_IMPORT_FIELD_CONFLICT'), 'without the view');
    const changed = applyAdministratorChanges(target, parseDraftChanges([{ path: 'album.artists', base: [], value: [entry(2, 'Typed Artist')] }, { path: `tracks.${slotA}.title`, base: '', value: 'Short' }], manifest, target.draft), shown);
    assert.deepEqual([changed, target.draft.album.artists.map(value => value.name), target.draft.tracks[0].title], [['album.artists', `tracks.${slotA}.title`], ['Typed Artist'], 'Short']);
    // A value the view shows unchanged is compared as before.
    assert.deepEqual(importDraftV2View(draft(), manifest, 'a'.repeat(24)), draft());
});

test('an approval is format 3 with entries of a key, name and primary or featured role, a named label or none, Disc Number fields, and 1 to 50 frozen Artists', () => {
    const frozen = { artists: [{ entryKey: key(1), artistId: 'a'.repeat(24), newArtist: true, candidateRevision: null }], label: null };
    const several = withAlbum({ artists: [entry(1, 'A'), entry(2, 'B'), entry(3, 'C', 'featured')], label: { name: 'Label', musicBrainzId: null } });
    for (const [label, snapshot] of [['one primary', draft()], ['several entries and a label', several], ['no entries (an append)', withAlbum({ artists: [] })], ['featured only', withAlbum({ artists: [entry(1, 'A', 'featured')] })]] as const) {
        assert.equal(importPublicationFormat({ schemaVersion: 3, snapshot, ...frozen }), 3, label); assert.equal(importPublicationSupported({ schemaVersion: 3, snapshot, ...frozen }), true, label);
    }
    assert.equal(importPublicationFormat({ schemaVersion: 3, snapshot: several, ...frozen, label: { organizationId: 'b'.repeat(24), newOrganization: true, candidateRevision: null } }), 3);
    const fifty = Array.from({ length: 50 }, () => frozen.artists[0]);
    assert.equal(importPublicationFormat({ schemaVersion: 3, snapshot: draft(), artists: fifty, label: null }), 3);
    const tracks = draft().tracks;
    for (const [label, value] of [
        ['no frozen Artists', { snapshot: draft(), label: null }], ['an empty Artist list', { snapshot: draft(), artists: [], label: null }], ['51 Artists', { snapshot: draft(), artists: [...fifty, frozen.artists[0]], label: null }],
        ['an Artist that is not a record', { snapshot: draft(), artists: ['a'.repeat(24)], label: null }], ['no frozen label', { snapshot: draft(), artists: frozen.artists }], ['a label that is not a record', { snapshot: draft(), ...frozen, label: 'x' }],
        ['an entry without a key', { snapshot: withAlbum({ artists: [{ ...entry(1, 'A'), key: undefined as unknown as string }] }), ...frozen }], ['an unknown role', { snapshot: withAlbum({ artists: [{ ...entry(1, 'A'), role: 'performer' as 'primary' }] }), ...frozen }],
        ['an unnamed label', { snapshot: withAlbum({ label: { musicBrainzId: null } as unknown as ImportDraftV2['album']['label'] }), ...frozen }], ['a missing Disc Number', { snapshot: { ...draft(), tracks: [tracks[0], { slotId: slotB, title: '', trackNumber: null }] }, ...frozen }],
        ['an artistName beside entries', { snapshot: { ...draft(), album: { ...draft().album, artistName: 'A' } }, ...frozen }]
    ] as const) assert.equal(importPublicationFormat({ schemaVersion: 3, ...value } as Parameters<typeof importPublicationFormat>[0]), null, label);
    assert.equal(importPublicationFormat({ schemaVersion: 4, snapshot: draft(), ...frozen }), null, 'a newer format');
});

test('a format-2 approval may leave every Disc Number unknown, as long as each track has the field', () => {
    const snapshot = draft(); snapshot.tracks = snapshot.tracks.map(track => ({ ...track, discNumber: null }));
    assert.equal(importPublicationFormat({ schemaVersion: 2, snapshot }), 2);
});

test('the approval digest binds the shown draft, decisions, cover and staged bytes in any key order, and nothing an approval does not show', () => {
    const decision = { scope: 'album', slotId: null, entryKey: null, boundName: null as string | null, action: 'create-distinct', candidateId: null, candidateRevision: null };
    const shown = { draft: draft(), decisions: [decision], selectedCoverSlotId: 'cover' as string | null, assets: [{ slotId: 'cover', state: 'ready', sha256: 'a'.repeat(64) }], tagOnly: { artists: false, label: false } }, base = importApprovalDigest(shown);
    assert.match(base, /^[a-f0-9]{64}$/);
    const reverse = <T extends object>(value: T) => Object.fromEntries(Object.entries(value).reverse()) as T;
    assert.equal(importApprovalDigest(reverse({ ...shown, draft: reverse({ ...shown.draft, album: reverse(shown.draft.album) }), decisions: shown.decisions.map(reverse), assets: shown.assets.map(reverse) })), base);
    // Asset fields beyond its slot, state and bytes are not shown as approval content.
    assert.equal(importApprovalDigest({ ...shown, assets: shown.assets.map(asset => ({ ...asset, byteLength: 9, contentType: 'image/png' })) }), base);
    for (const [label, change] of [
        ['a draft value', (value: typeof shown) => { value.draft.tracks[1].discNumber = 2; }], ['an Artist entry', (value: typeof shown) => { value.draft.album.artists[0].joinPhrase = ' & '; }],
        ['a decision', (value: typeof shown) => { value.decisions[0].action = 'skip'; }], ['the cover', (value: typeof shown) => { value.selectedCoverSlotId = null; }],
        ['an asset state', (value: typeof shown) => { value.assets[0].state = 'deleting'; }], ['asset bytes', (value: typeof shown) => { value.assets[0].sha256 = 'b'.repeat(64); }],
        ['a bound name', (value: typeof shown) => { value.decisions[0].boundName = 'Lorem Ensemble'; }],
        ['the Artist entries resting only on file tags', (value: typeof shown) => { value.tagOnly.artists = true; }], ['the label resting only on file tags', (value: typeof shown) => { value.tagOnly.label = true; }]
    ] as const) { const copy = structuredClone(shown); change(copy); assert.notEqual(importApprovalDigest(copy), base, label); }
    // The detail digests exactly what it shows; actor, receipts, revision, analysis and suggestions leave it unchanged.
    const detail = adminImportDetail(loadV2(), actor, true), unshown = loadV2();
    // The fixture's Artist entries and label are automatic, so the confirmation marks both as resting only on file tags.
    assert.equal(detail.approvalDigest, importApprovalDigest({ draft: detail.draft, decisions: detail.decisions, selectedCoverSlotId: detail.selectedCoverSlotId, assets: detail.assets, tagOnly: { artists: true, label: true } }));
    Object.assign(unshown, { revision: unshown.revision + 5, receipts: [], analysis: { ...unshown.analysis, generation: unshown.analysis.generation + 1 }, suggestions: [] });
    assert.equal(adminImportDetail(unshown, '0000000000000000000000b2', false).approvalDigest, detail.approvalDigest);
    const retitled = loadV2(); (retitled.draft as ImportDraftV2).album.title = 'Retitled'; assert.notEqual(adminImportDetail(retitled, actor, true).approvalDigest, detail.approvalDigest);
    // Reviewing the label (it becomes the administrator's own) changes what the confirmation marks, and so the digest; automatic
    // writes elsewhere counted by valueRevision alone do not.
    const reviewed = loadV2(); reviewed.draftOrigins!['album:label'] = 'administrator'; assert.notEqual(adminImportDetail(reviewed, actor, true).approvalDigest, detail.approvalDigest);
    assert.equal(adminImportDetail({ ...loadV2(), valueRevision: 9 }, actor, true).approvalDigest, detail.approvalDigest);
    // The Web contract fixture (web/src/features/admin/adminApi.test.ts) echoes this value. Changing what the digest covers makes
    // every open confirmation ADMIN_IMPORT_APPROVAL_STALE across that deploy, so both must be updated deliberately.
    assert.equal(detail.approvalDigest, 'e3fe4303d00be9a0834356a317c65c1e8c7417618fc51471f9fe55284f6d9df9');
});

test('converting a project saved before Draft v2 keeps its approval digest, so an approval built on its view stays current', () => {
    for (const name of v1Fixtures) {
        const doc = load(name), shown = adminImportDetail(doc, actor, true).approvalDigest; convertLegacyImportProject(doc);
        assert.equal(adminImportDetail(doc, actor, true).approvalDigest, shown, name);
    }
});
